package sn.ticket.service;
import sn.ticket.model.User; import sn.ticket.repo.Repos; import org.springframework.stereotype.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import java.util.*; import java.time.*; import java.security.*;
@Service public class AuthService { private final Repos.Users users;private final BCryptPasswordEncoder crypt=new BCryptPasswordEncoder();private final Map<String,User> sessions=new HashMap<>();private final SecureRandom random=new SecureRandom(); public AuthService(Repos.Users u){users=u;} public String login(String email,String password){User u=users.findByEmail(email.toLowerCase()).orElseThrow(()->new SecurityException("Identifiants invalides."));if(!"ADMIN".equals(u.role)||!crypt.matches(password,u.passwordHash))throw new SecurityException("Identifiants invalides.");byte[] b=new byte[32];random.nextBytes(b);String t=Base64.getUrlEncoder().withoutPadding().encodeToString(b);sessions.put(t,u);return t;} public User require(String header){if(header==null||!header.startsWith("Bearer "))throw new SecurityException("Authentification requise.");User u=sessions.get(header.substring(7));if(u==null)throw new SecurityException("Session invalide.");return u;} }
